'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),E=require('./features');
const root=path.resolve(__dirname,'..'),out=path.join(root,'evidence/editor_v032'),rom=fs.readFileSync(path.join(root,'originals/naruto_konoha_bearteam_simp.gba')),hash=b=>crypto.createHash('sha256').update(b).digest('hex'),checks=[];const test=(name,fn)=>{fn();checks.push(name);console.log('PASS',name);};
test('all 62 user labels match supplied final file and native glyphs',()=>{const p=JSON.parse(fs.readFileSync('/mnt/c/Users/APP/Downloads/火影字库_中文对应_20261018 (1).json')),m=new E.Editor(rom);assert.equal(Object.keys(p.labels).length,62);for(const [c,label]of Object.entries(p.labels)){assert.equal(m.mapping[parseInt(c,16)],label);assert(E.glyph(rom,parseInt(c,16)).some(v=>v));}});
test('native pickup dispatch and text tables agree with item names',()=>{const m=new E.Editor(rom);assert.equal(new Map(m.objectChoices(1)).get(1),'十字手里剑');assert.equal(new Map(m.objectChoices(1)).get(93),'超万能丸');assert.equal(new Map(m.objectChoices(2)).get(3),'钢石');assert.equal(m.objectName({type:3,target:12}),'李洛克的专属修行卷轴');assert.equal(m.objectName({type:4,target:62}),'岸本齐史的认识卡');for(const [index,target]of [[0,0x8081600],[1,0x808173c],[2,0x808180c],[3,0x80818e4],[4,0x8081984]])assert.equal(E.u32(rom,0x815e4+index*4),target);});
test('every original preset item resolves a name and lies within map bounds',()=>{const m=new E.Editor(rom);let count=0;for(let s=1;s<=46;s++)for(let sub=0;sub<3;sub++){const map=m.mapData(s);for(const o of m.objects(s,sub).filter(o=>o.type)){assert(!m.objectName(o).includes('未识别'),JSON.stringify(o));assert(o.x<map.width&&o.y<map.height);count++;}}assert.equal(count,165);});
test('blank preset records do not consume runtime slot numbers',()=>{const m=new E.Editor(rom);for(let i=0;i<16;i++)m.setObject(1,0,i,{type:0,target:0,x:0,y:0});m.setObject(1,0,5,{type:2,target:3,x:1,y:2});assert.equal(m.objectSlot(1,0,0)[0].index,5);assert.equal(m.objectSlot(1,0,1).length,0);});
test('conditional scroll and card skips expose all possible runtime-slot candidates',()=>{const m=new E.Editor(rom);for(let i=0;i<16;i++)m.setObject(1,0,i,{type:0,target:0,x:0,y:0});for(const [i,type,target]of [[0,3,12],[1,4,62],[5,2,3]])m.setObject(1,0,i,{type,target,x:i,y:2});assert.deepEqual(m.objectSlot(1,0,0).map(o=>o.index),[0,1,5]);assert.deepEqual(m.objectSlot(1,0,1).map(o=>o.index),[1,5]);assert.deepEqual(m.objectSlot(1,0,2).map(o=>o.index),[5]);assert.equal(m.objectSlot(1,0,3).length,0);});
test('placing item changes only its four preset bytes and survives project and ROM reopen',()=>{const m=new E.Editor(rom),o=m.objects(1,0)[0];m.transaction('move',()=>m.setObject(1,0,0,{...o,target:16,x:6,y:6}));const project=m.project(hash(rom)),q=new E.Editor(rom);q.importProject(project,hash(rom));assert.deepEqual(q.objects(1,0),m.objects(1,0));const result=q.build(()=>new Uint8Array(32).fill(255));for(let i=0;i<rom.length;i++)if(rom[i]!==result[i])assert(i>=o.offset&&i<o.offset+4);assert.equal(new E.Editor(result).objectName(new E.Editor(result).objects(1,0)[0]),'蛤蟆油');m.undo();assert.equal(hash(m.build()),hash(rom));});
test('original, role swap and event sample export unchanged when only opened',()=>{for(const file of ['originals/naruto_konoha_bearteam_simp.gba','build/naruto_role_swap_v0.1.5_EXPERIMENTAL.gba','build/naruto_fog_harbor_sample_v0.2.0.gba']){const bytes=fs.readFileSync(path.join(root,file)),m=new E.Editor(bytes);assert.equal(hash(m.build()),hash(bytes));assert.equal(m.characterName(32),'卡多的手下');}});
fs.writeFileSync(path.join(out,'objects_core_tests.json'),JSON.stringify({result:'pass',kind:'native table and dispatch inspection, data roundtrip; item gameplay not run',checks},null,2));
